import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

export default function AdminQuestions() {
  const navigate = useNavigate();
  const [questions, setQuestions] = useState([]);
  const [topics, setTopics] = useState([]);
  const [subtopics, setSubtopics] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({
    subtopicId: '',
    questionText: '',
    optionA: '',
    optionB: '',
    optionC: '',
    optionD: '',
    correctAnswer: 'A',
    explanation: '',
    difficulty: 'Easy',
    questionType: 'MCQ'
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  useEffect(() => {
    fetchQuestions();
    fetchTopics();
  }, []);

  const fetchQuestions = () => {
    api.get('/admin/questions')
      .then(res => {
        setQuestions(Array.isArray(res.data) ? res.data : []);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  };

  const fetchTopics = () => {
    api.get('/admin/topics')
      .then(res => setTopics(Array.isArray(res.data) ? res.data : []))
      .catch(() => {});
  };

  const fetchSubtopics = (topicId) => {
    api.get(`/questions/subtopics/${topicId}`)
      .then(res => setSubtopics(Array.isArray(res.data) ? res.data : []))
      .catch(() => {});
  };

  const handleSubmit = async () => {
    if (!form.subtopicId || !form.questionText || !form.optionA ||
        !form.optionB || !form.optionC || !form.optionD) {
      setError('Please fill all fields!');
      return;
    }
    try {
      await api.post('/admin/questions', form);
      setSuccess('Question added successfully! ✅');
      setError('');
      setForm({
        subtopicId: '', questionText: '',
        optionA: '', optionB: '', optionC: '', optionD: '',
        correctAnswer: 'A', explanation: '',
        difficulty: 'Easy', questionType: 'MCQ'
      });
      setShowForm(false);
      fetchQuestions();
    } catch {
      setError('Failed to add question!');
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this question?')) return;
    try {
      await api.delete(`/admin/questions/${id}`);
      setSuccess('Question deleted! ✅');
      fetchQuestions();
    } catch {
      setError('Failed to delete!');
    }
  };

  return (
    <div className="app-layout">
      {/* Admin Sidebar */}
      <div className="sidebar">
        <div className="sidebar-brand">
          <span>👨‍💼 Admin Panel</span>
        </div>
        <nav className="sidebar-nav">
          <div className="nav-section-title">MANAGE</div>
          <a className="nav-item" onClick={() => navigate('/admin/dashboard')}>
            📊 Dashboard
          </a>
          <a className="nav-item active" onClick={() => navigate('/admin/questions')}>
            ❓ Questions
          </a>
          <a className="nav-item" onClick={() => navigate('/admin/students')}>
            🎓 Students
          </a>
        </nav>
      </div>

      <div className="main-content fade-in">
        <div className="page-header">
          <div>
            <h1>❓ Manage Questions</h1>
            <p style={{ color: 'var(--mid)', fontSize: '0.9rem' }}>
              Add, view, delete questions
            </p>
          </div>
          <button className="btn-primary"
            onClick={() => setShowForm(!showForm)}>
            {showForm ? '✕ Cancel' : '➕ Add Question'}
          </button>
        </div>

        {error && <div className="error-msg">{error}</div>}
        {success && (
          <div style={{
            background: '#00b89420', color: '#00b894',
            padding: '0.8rem', borderRadius: '8px',
            marginBottom: '1rem'
          }}>
            {success}
          </div>
        )}

        {/* Add Question Form */}
        {showForm && (
          <div className="topic-card" style={{ marginBottom: '2rem' }}>
            <div style={{ padding: '1.5rem' }}>
              <h3 style={{ marginBottom: '1rem' }}>➕ Add New Question</h3>

              {/* Topic Select */}
              <div className="form-group">
                <label>Topic</label>
                <select className="form-control"
                  onChange={e => fetchSubtopics(e.target.value)}>
                  <option value="">Select Topic</option>
                  {topics.map(t => (
                    <option key={t.id} value={t.id}>{t.name}</option>
                  ))}
                </select>
              </div>

              {/* Subtopic Select */}
              <div className="form-group">
                <label>Subtopic</label>
                <select className="form-control"
                  value={form.subtopicId}
                  onChange={e => setForm({ ...form, subtopicId: e.target.value })}>
                  <option value="">Select Subtopic</option>
                  {subtopics.map(s => (
                    <option key={s.id} value={s.id}>{s.name}</option>
                  ))}
                </select>
              </div>

              {/* Question */}
              <div className="form-group">
                <label>Question</label>
                <textarea className="form-control" rows={3}
                  placeholder="Enter question..."
                  value={form.questionText}
                  onChange={e => setForm({ ...form, questionText: e.target.value })} />
              </div>

              {/* Options */}
              {['A', 'B', 'C', 'D'].map(opt => (
                <div className="form-group" key={opt}>
                  <label>Option {opt}</label>
                  <input className="form-control"
                    placeholder={`Option ${opt}`}
                    value={form[`option${opt}`]}
                    onChange={e => setForm({ ...form, [`option${opt}`]: e.target.value })} />
                </div>
              ))}

              {/* Correct Answer */}
              <div className="form-group">
                <label>Correct Answer</label>
                <select className="form-control"
                  value={form.correctAnswer}
                  onChange={e => setForm({ ...form, correctAnswer: e.target.value })}>
                  {['A', 'B', 'C', 'D'].map(o => (
                    <option key={o} value={o}>{o}</option>
                  ))}
                </select>
              </div>

              {/* Explanation */}
              <div className="form-group">
                <label>Explanation</label>
                <input className="form-control"
                  placeholder="Explain the answer..."
                  value={form.explanation}
                  onChange={e => setForm({ ...form, explanation: e.target.value })} />
              </div>

              {/* Difficulty */}
              <div className="form-group">
                <label>Difficulty</label>
                <select className="form-control"
                  value={form.difficulty}
                  onChange={e => setForm({ ...form, difficulty: e.target.value })}>
                  <option>Easy</option>
                  <option>Medium</option>
                  <option>Hard</option>
                </select>
              </div>

              <button className="btn-primary" onClick={handleSubmit}>
                ✅ Save Question
              </button>
            </div>
          </div>
        )}

        {/* Questions List */}
        {loading ? (
          <div className="loading-wrap"><div className="spinner"></div></div>
        ) : questions.length === 0 ? (
          <div className="empty-state">
            <div className="e-icon">📭</div>
            <h3>No questions yet</h3>
            <p>Add your first question!</p>
          </div>
        ) : (
          <div>
            <h3 style={{ marginBottom: '1rem' }}>
              📋 All Questions ({questions.length})
            </h3>
            {questions.map((q, i) => (
              <div className="topic-card" key={q.id}
                style={{ marginBottom: '1rem' }}>
                <div style={{ padding: '1rem' }}>
                  <div style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'flex-start'
                  }}>
                    <div style={{ flex: 1 }}>
                      <p style={{ fontWeight: 600 }}>
                        {i + 1}. {q.questionText}
                      </p>
                      <p style={{ color: 'var(--mid)', fontSize: '0.85rem' }}>
                        A: {q.optionA} | B: {q.optionB} |
                        C: {q.optionC} | D: {q.optionD}
                      </p>
                      <p style={{ color: '#00b894', fontSize: '0.85rem' }}>
                        ✅ Answer: {q.correctAnswer} |
                        🎯 {q.difficulty}
                      </p>
                    </div>
                    <button
                      onClick={() => handleDelete(q.id)}
                      style={{
                        background: '#ff4444',
                        color: 'white',
                        border: 'none',
                        borderRadius: '6px',
                        padding: '0.4rem 0.8rem',
                        cursor: 'pointer',
                        marginLeft: '1rem'
                      }}>
                      🗑 Delete
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
